//@@ START - asset_yld
// Asset Yield                                                                                             
// Column:ASSET_YLD
//========================================================
double SEG_COMP_UDF::seg_comp_asset_yld(int t) {
//^^^
if ( isRebaseClone && sm_peer_model  && t <= rebase_period ){
	return rebase_value(22,"asset_yld",t);
}



//^^^

#line 1 "asset_yld.SEG_COMP.for"
if (t < start_period || t > final_period)
	return NO_AVG;

// force calls for reporting
rates->yield_rate_90_day(t);
rates->yield_rate_10_year(t);
rates->equity_market_value_growth_us(t);
rates->equity_scenario_total_return_us(t);
rates->infl_rate_annual(t);

if (nb_flag && t == start_period
	&& valn_period == 0)
	return NO_AVG;

// force order
if (t > start_period)
	asset_yld(t - 1);

// force call all asset yields
asset_yld_inv(t);

if (!alm_flag)
	{
	double hedge_asset_yld_adj = 0.0;

	// Adjust for hedges in liability only runs only for FIA and IUL
	{
	#if defined(__FIA_LIAB_H_) || defined(__IUL_LIAB_H_)
	if (t == start_period)
		{
		// estimate initial adjustment using next period growth
		if (fabs(hedge_mkt_val(t)) < model_point_amount_threshold)
			hedge_asset_yld_adj = 0.0;
		else
			hedge_asset_yld_adj = hedge_mkt_val_growth(t + 1) / hedge_mkt_val(t);
		}
	else
		{
		if (fabs(hedge_mkt_val(t - 1)) < model_point_amount_threshold)
			hedge_asset_yld_adj = 0.0;
		else
			hedge_asset_yld_adj = hedge_mkt_val_growth(t) / hedge_mkt_val(t - 1);
		}

	// Convert into effective annual rate
	hedge_asset_yld_adj = pow(1.0 + hedge_asset_yld_adj, 12.0) - 1.0;
	#endif
	}

	if (asset_yld_defn == DETERMINISTIC)
		return asset_yld_deterministic + hedge_asset_yld_adj;

	// else asset_yld_defn == STOCHASTIC
	return company->get_comp_rate(asset_yld_comp_rate_id, t) + hedge_asset_yld_adj;
	}
// call asset_yld in a_sub_port
sum_over_asset_sub_ports("asset_yld", t, BEFORE_SALE);

double asset_yld_calc = 0.0;

if (asset_yld_denom(t) < -aggregate_amount_threshold)
	asset_yld_calc = 0.0;

else if (asset_yld_denom(t) > aggregate_amount_threshold)
	{
	double asset_yld_numer = this->asset_yld_numer(t);
	double cash_int = this->cash_int(t);
	double borrowing_int = this->borrowing_int(t);
	double interim_cash_int = this->interim_cash_int(t);

	double asset_yld_numer_adj
	= asset_yld_numer
	  + cash_int
	  + borrowing_int
	  + interim_cash_int;

	double asset_yld_prelim
	= annual_yld(asset_yld_numer_adj,
				asset_yld_denom(t),
				EFFECTIVE_ANNUAL);

	asset_yld_calc = min(max(asset_yld_prelim, USLIB_MINIMUM_YIELD), USLIB_MAX_DOUBLE);
	}
else
	asset_yld_calc = min(max(cash_rate(t), USLIB_MINIMUM_YIELD), USLIB_MAX_DOUBLE);

if (res_ag38_8d_valn_flag)
	return min(asset_yld_calc, asset_yld_ag38_8d); 
		
if (t == start_period)
	{
	if (time_step_flag && valn_period > 0)
		return init_asset_yld;
		
	return asset_yld_calc;	
	}

return asset_yld_calc;

}

