//@@ START - distrib_earnings
// Distributable Earnings                                                                                             
// Column:DISTRIB_EARNINGS
//========================================================
double SEG_COMP_UDF::seg_comp_distrib_earnings(int t) {
//^^^
if ( isRebaseClone && sm_peer_model  && t <= rebase_period ){
	return rebase_value(124,"distrib_earnings",t);
}



//^^^

#line 1 "distrib_earnings.SEG_COMP.for"
if (t <= start_period || t > final_period)
	return NO_AVG;

// force call accumulated earnings for reporting
earnings_accum(t); 

if (tcm_flag && business_seg_flag)
	return bk_prof_aft_tax(t)
           + tgt_cap_effect(t);

double distrib_earnings
= undistrib_earnings(t - 1)
  + bk_prof_aft_tax(t)
  + tgt_cap_effect(t)
  + contribn_from_business_seg(t);

if (cal_mth(t) == 12 || last_period_indicator(t)
	|| (company->prof_distribn_mode == QUARTERLY 
         && (xint(cal_mth(t)) % 3 == 0))
	|| company->prof_distribn_mode == MONTHLY)
	return distrib_earnings;

return NO_AVG;

}

