//@@ START - free_surp
// Free Surplus                                                                                             
// Column:FREE_SURP
//========================================================
double SEG_COMP_UDF::seg_comp_free_surp(int t) {
//^^^
if ( isRebaseClone && sm_peer_model  && t <= rebase_period ){
	return rebase_value(146,"free_surp",t);
}



//^^^

#line 1 "free_surp.SEG_COMP.for"
if (nb_flag || (tcm_flag && business_seg_flag) || t < start_period || t > final_period)
	return NO_AVG;

// Force a call to free surplus at market
if (alm_flag)
	{
	free_surp_at_mkt(t);

	if (t == final_period)
		free_surp_at_mkt_ending(t);
	}

if (t == start_period)
	{
	if (!alm_flag)	
		return company->init_free_surp;		

	return inv_asset(t)
		   + pol_loan(t)
		   + deferred_net_prem(t)
		   - reins_deferred_net_prem(t)
		   + loc_asset(t)
		   + hedge_mkt_val(t)
		   - (stat_unearn_prem_res(t)
		      - reins_stat_unearn_prem_res(t)
		      + stat_claim_res(t)
			  + stat_prem_waiver_res(t)
		      - reins_stat_claim_res(t)
			  - reins_stat_prem_waiver_res(t)
		      + stat_res(t)
		      - reins_stat_res(t)
			  + stat_res_sa_exp_allow(t))
		   - imr(t)
		   - avr(t)
		   - tgt_cap(t)
		   - (div_liab(t)	
		      - reins_div_liab(t))
		   - undistrib_earnings(t);
	}  

return free_surp(t - 1) + free_surp_incr(t);

}

//@@ END

//@@ START - free_surp_at_mkt
// Free Surplus at Market                                                                                             
// Column:FREE_SURP_AT_MKT
//========================================================
double SEG_COMP_UDF::seg_comp_free_surp_at_mkt(int t) {
//^^^
if ( isRebaseClone && sm_peer_model  && t <= rebase_period ){
	return rebase_value(147,"free_surp_at_mkt",t);
}



//^^^

#line 1 "free_surp_at_mkt.SEG_COMP.for"
if (nb_flag || !alm_flag || (tcm_flag && business_seg_flag) || t < start_period || t > final_period)
	return NO_AVG;

if (mths_to_next_mkt_val_calc(t) != 0 && t != 0)
	return 0.0;

// Note: Internally projected hedge assets are included in mkt_val and bk_val
if (t == start_period)
	return inv_asset(t)
		   + pol_loan(t)
		   + deferred_net_prem(t)
		   - reins_deferred_net_prem(t)
		   + loc_asset(t)
		   - (stat_unearn_prem_res(t)
		      - reins_stat_unearn_prem_res(t)
		      + stat_claim_res(t)
			  + stat_prem_waiver_res(t)
		      - reins_stat_claim_res(t)
			  - reins_stat_prem_waiver_res(t)
		      + stat_res(t)
		      - reins_stat_res(t))
		   - imr(t)
		   - avr(t)
		   - tgt_cap(t)
		   - (div_liab(t)	
		      - reins_div_liab(t))
   	    + mkt_val(t)
  	     - bk_val(t);
  
return free_surp_bef_distribn(t)
       - distribn(t)
       + mkt_val(t)
       - bk_val(t);

}

