	return NO_AVG;

// force call for reporting
gaap_surp_unrealzd_cap_gain_incr(t);

return cap_gain_res(t)
       + cap_gain_undistrib_earnings(t)
	   - unrealzd_cap_gain_incr(t)
       + cap_gain_tgt_cap(t) 
       - reins_cap_gain_res(t) 
       - (gaap_cap_gain_res(t) 
          - gaap_unrealzd_cap_gain_incr(t)
          - reins_gaap_cap_gain_res(t));

