//@@ START - gaap_cap_gain_res
// GAAP Capital Gain on Reserves                                                                                             
// Column:GAAP_CAP_GAIN_RES
//========================================================
double SEG_COMP_UDF::seg_comp_gaap_cap_gain_res(int t) {
//^^^
if ( isRebaseClone && sm_peer_model  && t <= rebase_period ){
	return rebase_value(160,"gaap_cap_gain_res",t);
}



//^^^

#line 1 "gaap_cap_gain_res.SEG_COMP.for"
if (!gaap_flag || !alm_flag || t <= start_period || t > final_period)
	return NO_AVG;
	
if ((fabs(stat_res(t - 1) + div_liab(t - 1)
    	- deferred_net_prem(t - 1) - loc_asset(t - 1) - pol_loan(t - 1)))
     > rate_ratio_threshold)
	return cap_gain_res(t)
	        * (gaap_liab_net(t - 1)
               - pol_loan(t - 1))
	        / (stat_res(t - 1) 
    	       + div_liab(t - 1)
    	       - deferred_net_prem(t - 1)
               - loc_asset(t - 1) 
    	       - pol_loan(t - 1)) 
	       + gaap_inc_unrealzd_cap_gain_incr(t);

return cap_gain_res(t)
	   + (pow((1.0 + eff_cap_gains_rate(t)),(1.0 / 12.0)) - 1)
	         * (gaap_liab_net(t - 1) - pol_loan(t - 1))
	   + gaap_inc_unrealzd_cap_gain_incr(t);

}

