//^^^

#line 1 "gaap_inc_bef_tax.SEG_COMP.for"
if (!gaap_flag || t <= start_period || t > final_period)
	return NO_AVG;

double gaap_inc_bef_tax = 0.0;

// force call actual gross profits and actual gross margin
double agp = sum_over_sfas97rd("agp", t, GROSS);
double agm = sum_over_sfas120("agm", t, GROSS);

//force calls for reporting
gaap_capzd_acq_exp(t);
gaap_capzd_comm_bom(t);
gaap_capzd_comm_eom(t);
gaap_capzd_prem_bonus(t);
gaap_capzd_reins_yrt_cost(t);
sum_over_sfas60("detail_rpt_driver", t, GROSS);
sum_over_sfas97lp("detail_rpt_driver", t, GROSS);
sum_over_sfas60("inv_inc", t, GROSS);
sum_over_sfas91("inv_inc", t, GROSS);
sum_over_sfas97lp("inv_inc", t, GROSS);
sum_over_sfas97rd("inv_inc", t, GROSS);
sum_over_sfas120("inv_inc", t, GROSS);
