//@@ START - initialize
// Initialize                                                                                             
// Column:INITIALIZE
//========================================================
double SEG_COMP_UDF::seg_comp_initialize(int t) {
//^^^



//^^^

#line 1 "initialize.SEG_COMP.for"
if (t != 0)
	return NO_AVG;

if (time_step_flag && valn_period > 0 && !hedge_valn_flag)
	read_state_of_world_financial();
else
	{// Capture IMR amortization amounts into array
	if (imr_flag)
		{
		init_imr_amortzn_amt.resize(imr_max_amortzn_yrs + 1);

		// Lookup key is cal_yr column for each future year
		for (int row = 0; row <= imr_max_amortzn_yrs; row++)
			{
			cal_yr_lookup = cal_yr((row - 1) * 12);
			seg_id = seg_id;
			init_imr_amortzn_amt[row] = imr_amortzn_from_prior_asset_sale;
			}
		}
	}

setup_liab_model_points(t);

if (alm_flag)
	{
	// create investment sales and rebalancing detail report file
	// create investment strategy detail report file
	if(asset->asset_detail_rpt_inv_strat_defn == YES)
		{
		xstring output_name = "";
		xstring output_file_name = replaceWildcards(output_location());
		output_file_name = xstring(output_file_name(0 , output_file_name.find_first_of("~")));

		asset_detail_rpt_inv_strat_id
		= output_file_name
		  + "_InvStratDetail"
		  + "_" + seg_id
		  + "_" + xstring(proj_task_loop_num)
		  + ".csv";

		SALFile.open((xstring)asset_detail_rpt_inv_strat_id);
		SALFile.setf(ios::fixed, ios::floatfield);

		if (!SALFile)
			throw FatalError("Cannot open asset detail investment strategy report file = " + asset_detail_rpt_inv_strat_id
							 + ". Check that the directory has been created and that you have permission to write it.");
		else
			SALFile << endl
					<< "Investment Strategy Detail Report for "
					<< get_file_name(output_location())
					<< " Segment " << seg_id << endl;
		}

	setup_asset_model_points(t);

	setup_asset_sub_ports();

	setup_inv_strategy(t);

	// capture cash balance addition for segment
	for (asset->init_cash_bal_map_iter = asset->init_cash_bal_map.begin();
	     asset->init_cash_bal_map_iter != asset->init_cash_bal_map.end();
         asset->init_cash_bal_map_iter++)
		{		
		xstring index_val = asset->init_cash_bal_map_iter->first;
		
		if (index_val.find(seg_id) < string::npos)
			init_cash_addn += asset->init_cash_bal_map[index_val];
		}

	}

setup_life_pba_elements();
setup_va_pba_elements();
setup_ann_pba_elements();

if (gaap_flag)
	{
	if (gaap_ldti_valn_flag || !valn_flag)
		setup_sfas60_cohorts();

	if (sfas91_valn_flag || !valn_flag)
		setup_sfas91_cohorts();

	if (gaap_ldti_valn_flag || !valn_flag)
		setup_sfas97lp_cohorts();
	
	if ((sop031_valn_flag || sfas97rd_valn_flag) || !valn_flag)
		setup_sfas97rd_cohorts();

	if (gaap_ldti_valn_flag || !valn_flag)
		setup_sfas120_cohorts();
	}

// Only define hedge groups for FIA and IUL for ALM projections
#if defined(__FIA_LIAB_H_) || defined(__IUL_LIAB_H_)
if (alm_flag)
	setup_hedge_groups(t);
#endif

// For VA, setup hedge groups for all projections
#if defined(__VA_LIAB_H_)
setup_hedge_groups();
#endif

get_hedge_items();
		
return 1.0;

}

