//@@ START - inv_asset
// Invested Assets                                                                                             
// Column:INV_ASSET
//========================================================
double SEG_COMP_UDF::seg_comp_inv_asset(int t) {
//^^^
if ( isRebaseClone && sm_peer_model  && t <= rebase_period ){
	return rebase_value(295,"inv_asset",t);
}



//^^^

#line 1 "inv_asset.SEG_COMP.for"
if (t < start_period || t > final_period)
	return NO_AVG;

if (nb_flag && t == start_period
	&& valn_period == 0)
	return NO_AVG;

// force call separate account assets
asset_sa(t);

if (alm_flag)
	{
	double inv_asset = cash(t);
	
	inv_asset += borrowing(t);
	inv_asset += interim_cash(t);
	inv_asset += bk_val_inv(t);
	inv_asset += accr_int(t);

	// force call hedge notional
	sum_over_hedge_grps("hedge_notional_amt", t); 

	// force call for reporting
	notional_amt(t);

	if (asset->asset_detail_rpt_inv_strat_flag(t))
		asset_detail_rpt_summary(t, "EOM", cash(t) + borrowing(t), interim_cash(t), inv_asset);

	return inv_asset;
	}


return liab_and_surp(t)
	   - pol_loan(t)
	   - (deferred_net_prem(t)
	      - reins_deferred_net_prem(t))
	   - loc_asset(t)
	   - hedge_mkt_val(t);

}

