// Investment Income on Undistributed Earnings                                                                                             
// Column:INV_INC_UNDISTRIB_EARNINGS
//========================================================
double SEG_COMP_UDF::seg_comp_inv_inc_undistrib_earnings(int t) {
//^^^
if ( isRebaseClone && sm_peer_model  && t <= rebase_period ){
	return rebase_value(309,"inv_inc_undistrib_earnings",t);
}



//^^^

#line 1 "inv_inc_undistrib_earnings.SEG_COMP.for"
if ((tcm_flag && business_seg_flag) || t <= start_period || t > final_period)
	return NO_AVG;
 
if (corp_seg_flag)
	{
	if (fabs(inv_asset(t - 1)) < rate_ratio_threshold)
		return NO_AVG;

	return inv_inc_on_invested_assets(t)
			* undistrib_earnings(t - 1)
			/ inv_asset(t - 1);
	}

if (fabs(inv_asset(t - 1) - tgt_cap(t - 1) - avr(t - 1)
		 - imr(t - 1) - free_surp(t - 1))
          < rate_ratio_threshold)
	return NO_AVG;

double inv_inc_wo_surp
	   = inv_inc_on_invested_assets(t)
         - inv_inc_tgt_cap(t)
         - inv_inc_free_surp(t);

return inv_inc_wo_surp
       * undistrib_earnings(t - 1)
       / (inv_asset(t - 1) - tgt_cap(t - 1) - avr(t - 1)
		  - imr(t - 1) - free_surp(t - 1));

}

