	sum_over_asset_sub_ports("eff_dur", t, END_OF_PERIOD);
	sum_over_asset_sub_ports("dur_for_transfer", t, END_OF_PERIOD);
	sum_over_asset_sub_ports("mkt_val", t, END_OF_PERIOD);
		
	return sum_over_assets("mkt_val", t, SUM_OVER_ALL, SUM_OVER_ALL, SUM_OVER_ALL, END_OF_PERIOD);
