	StrEnum::EnumValue pba_reins_defn_stoch_amt = sm_va_pba[0]->reins_defn;
	StrEnum::EnumValue pba_hedging_defn_stoch_amt = sm_va_pba[0]->hedging_defn;

	// Determine stochastic amount adjusted as unhedged stochastic amount
	// customize this code to change this treatment
	double stoch_amt_adjusted = 0.0;

	sm_va_pba[0]->pba_code = STOCH_CAP;
