	   + opt_pmt(t)
	   + cash_int(t)
	   + borrowing_int(t)
	   + interim_cash_int(t)
	   + cash_flow_int(t)
	   - tax_bk_prof_bef_sale(t)
	   - tax_tgt_cap_bef_sale(t)
	   - tax_free_surp_bef_sale(t);

