	return NO_AVG;

double reins_gaap_cost = 0.0;

// force call actual gross profits
double agp = sum_over_sfas97rd("agp", t, CEDED);
double agm = sum_over_sfas120("agm", t, CEDED);

//force calls for reporting
reins_gaap_capzd_comm_bom(t);
reins_gaap_capzd_comm_eom(t);
reins_gaap_capzd_prem_bonus(t);
sum_over_sfas60("detail_rpt_driver", t, CEDED);
