//========================================================
double SEG_COMP_UDF::seg_comp_tax_bk_prof_ytd(int t) {
//^^^
if ( isRebaseClone && sm_peer_model  && t <= rebase_period ){
	return rebase_value(615,"tax_bk_prof_ytd",t);
}



//^^^

#line 1 "tax_bk_prof_ytd.SEG_COMP.for"
if (t < start_period || t > final_period)
	return NO_AVG;

if (t == start_period)
	{
	if (time_step_flag && valn_period > 0)
		return init_tax_bk_prof_ytd;
		
	return NO_AVG;	
	}

double tax_rate = company->tax_rate;
double tax_rate_cap_gain = company->tax_rate_cap_gain;

if (!nb_flag || company->tax_loss_treatment == IMMEDIATE_LOSS_RECOGNITION)
	return taxable_inc_bk_prof_ytd(t) 
	       * tax_rate
	       + (realzd_cap_gain_res_ytd(t)
			  - reins_realzd_cap_gain_res_ytd(t)          
			  + realzd_cap_gain_undistrib_earnings_ytd(t))
	         * (tax_rate_cap_gain - tax_rate);

if (company->tax_loss_treatment == ZERO_TAX)
	return (taxable_inc_bk_prof_ytd(t)
	        - min(taxable_inc_bk_prof_ytd(t) + taxable_inc_tgt_cap_ytd(t), 0.0))
	       * tax_rate
	       + (realzd_cap_gain_res_ytd(t)
			  - reins_realzd_cap_gain_res_ytd(t)          
			  + realzd_cap_gain_undistrib_earnings_ytd(t))
	         * (tax_rate_cap_gain - tax_rate);

// company->tax_loss_treatment == TAX_LOSS_CARRYFORWARD	
return (taxable_inc_bk_prof_ytd(t) 
	    + taxable_inc_carryfwd_addn_ytd(t)
	    - taxable_inc_carryfwd_applied_ytd(t))
       * tax_rate
      + (realzd_cap_gain_res_ytd(t)
	     - reins_realzd_cap_gain_res_ytd(t)          
	     + realzd_cap_gain_undistrib_earnings_ytd(t))
 	   * (tax_rate_cap_gain - tax_rate);

}

