//@@ START - tgt_cap
// Target Capital                                                                                             
// Column:TGT_CAP
//========================================================
double SEG_COMP_UDF::seg_comp_tgt_cap(int t) {
//^^^
if ( isRebaseClone && sm_peer_model  && t <= rebase_period ){
	return rebase_value(674,"tgt_cap",t);
}



//^^^

#line 1 "tgt_cap.SEG_COMP.for"
if (!tgt_cap_flag || t < start_period || t > final_period)
	return NO_AVG;

if (nb_flag && t == start_period
	&& valn_period == 0)
	return NO_AVG;

// Target capital in corporate segment equals total target capital for company
// less target capital invested in business segments
if (corp_seg_flag)
	return company->tgt_cap(t)
	       - company->sum_over_segments("tgt_cap", t, BUSINESS_SEGMENTS);

if (tcm_flag && business_seg_flag
	&& alm_flag && t == start_period
	&& valn_period == 0)
	{
	// Set initial target capital to difference between initial assets and liabilities
	// This ensure there is no free surplus in business segment at the projection date

	// force call rbc
	rbc(t);

	double assets
	= pol_loan(t) 
		+ deferred_net_prem(t)
		+ loc_asset(t) 
		+ inv_asset(t)
		+ hedge_mkt_val(t);
	
	double liab
	= stat_unearn_prem_res(t)
		- reins_stat_unearn_prem_res(t)
		+ stat_claim_res(t)
		+ stat_prem_waiver_res(t)
		- reins_stat_claim_res(t)
		- reins_stat_prem_waiver_res(t)
		+ stat_res(t)
		- reins_stat_res(t)
		+ div_liab(t) 
		- reins_div_liab(t)
		+ avr(t)
		+ imr(t);

	return assets - liab;
	}

return rbc(t) 
       * company->tgt_cap_rbc_mult
       * tgt_cap_pct_inv_in_seg;

}

