//@@ START - undistrib_earnings
// Undistributed Earnings                                                                                             
// Column:UNDISTRIB_EARNINGS
//========================================================
double SEG_COMP_UDF::seg_comp_undistrib_earnings(int t) {
//^^^
if ( isRebaseClone && sm_peer_model  && t <= rebase_period ){
	return rebase_value(683,"undistrib_earnings",t);
}



//^^^

#line 1 "undistrib_earnings.SEG_COMP.for"
if ((tcm_flag && business_seg_flag) || t < start_period || t > final_period)
	return NO_AVG;

if (nb_flag && t == start_period
	&& valn_period == 0)
	return NO_AVG;

if (t == start_period)
	{
	if (time_step_flag && valn_period > 0)
		{
		return init_undistrib_earnings;
		}

	return NO_AVG;	
	}

if (cal_mth(t) == 12 || last_period_indicator(t)
	|| (company->prof_distribn_mode == QUARTERLY
        && xint(cal_mth(t)) % 3 == 0)
	|| company->prof_distribn_mode == MONTHLY)
	return NO_AVG;

return undistrib_earnings(t - 1)
	   + bk_prof_aft_tax(t)
	   - tgt_cap_incr(t)
	   + inv_inc_tgt_cap(t)
	   + cap_gain_tgt_cap(t)
	   - imr_impact_tgt_cap(t)
	   - tax_tgt_cap(t)
	   + contribn_from_business_seg(t);

}

