#line 1 "finalize_sfas120_cohorts.SEG_COMP.for"                                                                                   
void SEG_COMP::finalize_sfas120_cohorts(void)
{
#if defined(__SFAS120_GAAP_H_)

if (!sm_sfas120.size())
	return;

int cohorts = 0;
SFAS120_GAAP *current_cohort_element;

log_screen << "... Finalizing SFAS120 GAAP cohorts for Segment " << seg_id << MSG_USER;

map <int, long, less <int> >::iterator cohortmap_iter;
for (cohortmap_iter = sfas120_cohort_map.begin(); cohortmap_iter != sfas120_cohort_map.end(); cohortmap_iter++)
	{
	cohorts = cohortmap_iter->second;
	for (int rein_el = 0; rein_el < sm_sfas120[cohorts].size(); rein_el ++)
		{
		current_cohort_element = sm_sfas120[cohorts][rein_el];

		if (last_proj_period >= current_cohort_element->start_period 
			&& last_proj_period <= current_cohort_element->final_period)	
			current_cohort_element->finalize(final_period);
		}
	}
#endif

return;
}



