#line 1 "get_hedge_items.SEG_COMP.for"                                                                                   
void SEG_COMP::get_hedge_items(void)
{
if (hedge_gross_array.size() < HEDGE_ARRAY_SIZE)
	hedge_gross_array.resize(HEDGE_ARRAY_SIZE);
	
for (int i = 0; i < HEDGE_ARRAY_SIZE; i++)
	{
	if (hedge_gross_array[i].size() < final_period + 1)
		hedge_gross_array[i].resize(final_period + 1);

	for (int j = 0; j < final_period + 1; j++)
		{
		hedge_gross_array[i][j] = 0.0;		
		}
	}	

if (hedge_pregen_gross_results != "NONE")
	{
	deptaskinput hedge_gross_input;

	xstring hedge_file = replaceWildcards(hedge_pregen_gross_results);

	OutputFileReader ofr_gross;
	hedge_gross_input = ofr_gross.readFile(hedge_file.getStdStr(), {"cash_flow", "mkt_val", "task_loop", "group", "period"});
	
	xstring group_name;
	
	if (time_step_flag)
		group_name = xstring(proj_set_loop_num);
	else
		group_name = xstring(proj_task_loop_num);	

	if (!hedge_gross_input.size())
		{
		throw FatalError("Could not read pregenerated gross hedge file: " 
						  + hedge_file + " "
						  + "Please check your data.");
		}

	double hedge_cash_flow = 0.0;
	double hedge_mkt_val = 0.0;
	int period = 0;

	for (int row = 0; row < hedge_gross_input.size(); row++)
		{
		if (!eq(hedge_gross_input[row][2], group_name))
			continue;

		if (eq(hedge_gross_input[row][4], ""))//blank period signifies a PV or IRR column
			continue;

		period = atoi(hedge_gross_input[row][4].c_str());

		if (period < valn_period)
			continue;
		
		hedge_gross_array[HEDGE_CASH_FLOW][period - valn_period] = atof(hedge_gross_input[row][0].c_str()); 
		hedge_gross_array[HEDGE_MKT_VAL][period - valn_period] = atof(hedge_gross_input[row][1].c_str()); 
		}

	if (period == 0)
		throw FatalError("Pregenerated gross hedging file does not contain information for task loop = " + group_name + ". "
		                 + "Please check hedging file " + hedge_file + ".");

	if (valn_period > period)
		throw FatalError("Pregenerated gross hedging file does not contain information for time periods beginning at period " 
		                 + xstring(valn_period) + ". Please check hedging file " + hedge_file + ".");

	for (int i = period - valn_period + 1; i <= final_period; i++)
		{
		hedge_gross_array[HEDGE_CASH_FLOW][i] = hedge_gross_array[HEDGE_CASH_FLOW][i - 1];
		hedge_gross_array[HEDGE_MKT_VAL][i] = hedge_gross_array[HEDGE_MKT_VAL][i - 1];
		}
	}

if (reins_flag)
	{
	if (hedge_net_array.size() < HEDGE_ARRAY_SIZE)
		hedge_net_array.resize(HEDGE_ARRAY_SIZE);
		
	for (int i = 0; i < HEDGE_ARRAY_SIZE; i++)
		{
		if (hedge_net_array[i].size() < final_period + 1)
			hedge_net_array[i].resize(final_period + 1);
	
		for (int j = 0; j < final_period + 1; j++)
			{
			hedge_net_array[i][j] = 0.0;		
			}
		}	
	
	if (hedge_pregen_net_results != "NONE")
		{
		deptaskinput hedge_net_input;

		xstring hedge_file = replaceWildcards(hedge_pregen_net_results);

		OutputFileReader ofr_net;
		hedge_net_input = ofr_net.readFile(hedge_file.getStdStr(), {"cash_flow", "mkt_val", "task_loop", "group", "period"});

		xstring group_name;
	
		if (time_step_flag)
			group_name = xstring(proj_set_loop_num);
		else
			group_name = xstring(proj_task_loop_num);	

		if (!hedge_net_input.size())
			{
			throw FatalError("Could not read pregenerated net hedge file: " 
							  + hedge_file + " "
							  + "Please check your data.");
			}

		double hedge_cash_flow = 0.0;
		double hedge_mkt_val = 0.0;
		int period = 0;

		for (int row = 0; row < hedge_net_input.size(); row++)
			{
			if (!eq(hedge_net_input[row][2], group_name))
				continue;

			if (eq(hedge_net_input[row][4], ""))//blank period signifies a PV or IRR column
				continue;

			period = atoi(hedge_net_input[row][4].c_str());

			if (period < valn_period)
				continue;
		
			hedge_net_array[HEDGE_CASH_FLOW][period - valn_period] = atof(hedge_net_input[row][0].c_str()); 
			hedge_net_array[HEDGE_MKT_VAL][period - valn_period] = atof(hedge_net_input[row][1].c_str()); 
			}

			if (period == 0)
				throw FatalError("Pregenerated net hedging file does not contain information for task loop = " + group_name + ". "
								 + "Please check hedging file " + hedge_file + ".");

			if (valn_period > period)
				throw FatalError("Pregenerated net hedging file does not contain information for time periods beginning at period " 
								 + xstring(valn_period) + ". Please check hedging file " + hedge_file + ".");

		for (int i = period - valn_period + 1; i <= final_period; i++)
			{
			hedge_net_array[HEDGE_CASH_FLOW][i] = hedge_net_array[HEDGE_CASH_FLOW][i - 1];
			hedge_net_array[HEDGE_MKT_VAL][i] = hedge_net_array[HEDGE_MKT_VAL][i - 1];
			}

		}
	}

return;
}



