#line 1 "resize_seriatim_array.SEG_COMP.for"                                                                                   
void SEG_COMP::resize_seriatim_array(xstring col_name, int num_cohorts, int num_periods, enum seriatim_type type)
{
map <pair<xstring,seriatim_type>, SmartArray< SmartArray< SmartArray<double> > > >::iterator total_it;
pair<xstring,seriatim_type> name_pair = make_pair(col_name, type);

total_it = seriatim_totals.find(name_pair);

if (total_it != seriatim_totals.end()) //if column found
	seriatim_totals.erase(total_it);

seriatim_totals[name_pair]; // Allocate space in the map.
seriatim_totals[name_pair].resize(num_cohorts); //num of cohorts

for (int cohort_count = 0; cohort_count < num_cohorts; cohort_count++)
	{
	seriatim_totals[name_pair][cohort_count].resize(2);  //ceded/gross
	seriatim_totals[name_pair][cohort_count][0].resize(num_periods + 1); //num of periods
	seriatim_totals[name_pair][cohort_count][1].resize(num_periods + 1);
	}

return;
}



#line 1 "setup_ann_pba_elements.SEG_COMP.for"                                                                                   
void SEG_COMP::setup_ann_pba_elements(void)
{
#if defined(__ANN_PBA_PBA_H_)
if (!sm_ann_pba.size())
	return;

if (sm_ann_pba[0]->res_cap_calc_defn != NOT_APPLICABLE)
	log_screen << "... Initializing Annuity PBA for " << seg_id << MSG_USER;

int t = 0;

for (int pba_element = 0; pba_element < sm_ann_pba.size(); pba_element++)
	{
	sm_ann_pba[pba_element]->seg_element = this;
	sm_ann_pba[pba_element]->seg_id = seg_id;
	//sm_ann_pba[pba_element]->initialize(t); //Currently, there is nothing in this column, but will revisit for Gen2 if that changes
	}
#endif

return;
}



