#line 1 "setup_sfas120_cohorts.SEG_COMP.for"                                                                                   
void SEG_COMP::setup_sfas120_cohorts(void)
{
#if defined(__SFAS120_GAAP_H_)
if (!sm_sfas120.size())
	return;

if (is_first_proj_task_loop || num_of_proj_task_loops == 0
	|| restore_variables_ind == 1)
	{
	int cohort_mp_count = 0;
	int assigned_mp_count = 0;
	sfas120_cohort_map.clear();
							
	log_screen << "... Initializing SFAS120 for " << seg_id << MSG_USER;

	// Step 1: Initialize cohort map array (gross)
	
	for (int cohort = 0; cohort < sm_sfas120.size(); cohort++)
		{
		for (int rein_el = 0; rein_el < sm_sfas120[cohort].size(); rein_el++)
			{
			sm_sfas120[cohort][rein_el]->seg_element = this;
			sm_sfas120[cohort][rein_el]->seg_id = seg_id;
			sm_sfas120[cohort][rein_el]->cohort_id = gaap_cohorts_sfas120[cohort];

			cohort_mp_count = sm_sfas120[cohort][rein_el]->initialize(0);
			assigned_mp_count += cohort_mp_count;

			if (cohort_mp_count != 0 
			    || (sfas120_seriatim_cohort_used.size() > cohort 
			        && sfas120_seriatim_cohort_used[cohort]))
				{
				sfas120_cohort_map[cohort] = cohort;	
				}
			}	
		}
	
	// Step 2: Initialize cohort map array for reinsurance and resize sfas120 accordingly (ceded - coinsurance)				
	int cohorts_el = 0;

	map <int, long, less <int> >::iterator cohortmap_iter;
	for (cohortmap_iter = sfas120_cohort_map.begin(); cohortmap_iter != sfas120_cohort_map.end(); cohortmap_iter++)
		{
		cohorts_el = cohortmap_iter->first;

		if (sm_sfas120[cohorts_el][0]->cohort_coins_indicator)
			{
			sm_sfas120[cohorts_el].resize(2);
			sm_sfas120[cohorts_el][1]->seg_element = this;
			sm_sfas120[cohorts_el][1]->cohort_id = gaap_cohorts_sfas120[cohorts_el];

			sm_sfas120[cohorts_el][1]->initialize(0);
			}
		}
	}	
#endif

return;
}



