#line 1 "sum_over_asset_sub_ports.SEG_COMP.for"                                                                                   
double SEG_COMP::sum_over_asset_sub_ports(const xstring & /* CiProxyFormula */ column_name, const int /* CiProxyTime */ t, int sum_over_timing)
{
double total = 0;
double existing = 0;
double purch = 0;
int asset_sub_port = 0;
int col_num = 0;

#if defined(__A_SUBPORT_ASSET_H_)
// ensure order of asset processing
if (sum_over_timing >= BEFORE_BOM_PURCH && t > start_period)
	company->sm_inv_strategy[seg_num]->cash(t - 1);

if (sum_over_timing >= BEFORE_SALE && t > start_period)
	hedge_inv_amt_bom(t);

if (sum_over_timing >= BEFORE_PM_SALE && t > start_period)
	{
	company->sm_inv_strategy[seg_num]->cash_flow_planned_sale(t);
	hedge_sale_amt(t);
	}	

if (sum_over_timing >= BEFORE_NCF_SALE && t > start_period)
	company->sm_inv_strategy[seg_num]->cash_flow_rebal(t);

if (sum_over_timing >= BEFORE_EOM_PURCH && t > start_period)
	company->sm_inv_strategy[seg_num]->cash_net_neg_cash_flow_sale(t);

if (sum_over_timing >= END_OF_PERIOD)
	company->sm_inv_strategy[seg_num]->inv_amt(t);

//This function is used to sum over all the asset sub portfolios for a column.
//The column name passed in must be a column name in the asset sub portfolio model. 
if (company->sm_asset->sm_asset_sub_port.size() > 0)
	{
	col_num = company->sm_asset->sm_asset_sub_port[0]->Column(column_name).Number();

	if (col_num >= 0) //if column not found then ignore 
		{		
		int asset_sub_port_size = company->sm_asset->sm_asset_sub_port[seg_num].size();

		if (asset_sub_port_size > 0)
			{
			for (asset_sub_port = 0; asset_sub_port < asset_sub_port_size; asset_sub_port++)
				 {
				 total += company->sm_asset->sm_asset_sub_port[seg_num][asset_sub_port][0]->Column(col_num).Value(t);
				 existing += company->sm_asset->sm_asset_sub_port[seg_num][asset_sub_port][1]->Column(col_num).Value(t);
				 purch += company->sm_asset->sm_asset_sub_port[seg_num][asset_sub_port][2]->Column(col_num).Value(t);
				 }
			}
		}
	}
#endif

return total;
}



