#line 1 "sum_over_hedge_grps.SEG_COMP.for"                                                                                   
double SEG_COMP::sum_over_hedge_grps(const xstring &/* CiProxyFormula */column_name, const int /* CiProxyTime */ t)
{
int col_num = 0;
int hedge_group = 0;
int hedge_group_bucket = 0;
double total = 0;

#if defined(__HDG_GRP_COMP_H_)
if (sm_hedge_grp.size() > 0)
	{
	col_num = sm_hedge_grp[0]->Column(column_name).Number();

	if (col_num < 0) //if column not found then ignore 
		return 0.0;
		
	for (hedge_group = 0; hedge_group < sm_hedge_grp.size(); hedge_group++)
		{
		for (hedge_group_bucket = 0; hedge_group_bucket < sm_hedge_grp[hedge_group].size(); hedge_group_bucket++)
			total += sm_hedge_grp[hedge_group][hedge_group_bucket]->Column(col_num).Value(t);
		}
	}
#endif

return total;
}



