#line 1 "sum_over_sfas120.SEG_COMP.for"                                                                                   
double SEG_COMP::sum_over_sfas120(const xstring &/* CiProxyFormula */colname, const int /* CiProxyTime */ t, int cohort_reins_defn)
{
double total = 0.0;
int mp = 0;
int colnum = 0;
int reins_el = 0;

if (cohort_reins_defn == GROSS)
	reins_el = 0;
else //cohort_reins_defn == CEDED
	reins_el = 1;

#if defined(__SFAS120_GAAP_H_)
if (sm_sfas120.size())
	{
	int cohort = 0;
	SFAS120_GAAP *current_cohort_element;
	
	colnum = sm_sfas120[0][0]->Column(colname).Number();
	if (colnum >= 0)
		{
		map <int, long, less <int> >::iterator cohortmap_iter;
		for (cohortmap_iter = sfas120_cohort_map.begin(); cohortmap_iter != sfas120_cohort_map.end(); cohortmap_iter++)
			{
			cohort = cohortmap_iter->first;
			
			if (reins_el == 1
				&& !sm_sfas120[cohort][0]->cohort_coins_indicator)
				continue;
				
			current_cohort_element = sm_sfas120[cohort][reins_el];

			// skip future cohorts
			if (xint(cal_yr(t)) < current_cohort_element->cohort_yr)
				continue;

			if (t >= current_cohort_element->start_period 
				&& t <= current_cohort_element->final_period)
				total += current_cohort_element->Column(colnum).Value(t);
			}
		}
	}
#endif
return total;
}



