//constructor
SEG_COMP_persistent_object::SEG_COMP_persistent_object(const xstring &modelClassName,
		int isSm, ModelClass *owner, ModelClass *peer, int mainRebase, const char *name, ModelClass* arrayPersistentObj) :
			SEG_COMP(modelClassName, isSm, owner, peer, mainRebase, name, arrayPersistentObj), 
			mReadArray(true),
			pfl(0)

	, sm_ann_pba(SEG_COMP::sm_ann_pba)
	, sm_hedge_grp(SEG_COMP::sm_hedge_grp)
	, sm_sfas97rd(SEG_COMP::sm_sfas97rd)
	{


	normalModel = false;
   mModelType = ARRAY_FIXED; 

	sm_calling_model = owner;  // owner = 0 for main model
	sm_peer_model = peer;  // peer = 0 for rebase main model and its submodels
	isMainRebase = mainRebase;
	isRebaseClone = ! mainRebase;
	isForceRestoreModel = 1;
	main_rebase_model = (isMainRebase && rebasing_wanted);

	shrink();
}


//destructor
SEG_COMP::~SEG_COMP() {

    if (bIsInit)
		deInit_();  // call user defined destructor code
	if (sliding_wanted == SLIDING_TEST) {
   	show_sliding_windows();
	}
//	ModelClass* ann_pba_persObj = sm_ann_pba.getPersistentObject();
//	doAdopt(ann_pba_persObj, Node::COUNTED); // delete called by node dtor.
	if (sm_ann_pba.IsValidSubModelOfBaseModelClass()){
		sm_ann_pba.resize(0);
		delete sm_ann_pba.getPersistentObject();
		sm_ann_pba.mPersistentObj = 0;
	}

//	ModelClass* hedge_grp_persObj = sm_hedge_grp.getPersistentObject();
//	doAdopt(hedge_grp_persObj, Node::COUNTED); // delete called by node dtor.
	if (sm_hedge_grp.IsValidSubModelOfBaseModelClass()){
		sm_hedge_grp.resize(0);
		delete sm_hedge_grp.getPersistentObject();
		sm_hedge_grp.mPersistentObj = 0;
	}

//	ModelClass* sfas97rd_persObj = sm_sfas97rd.getPersistentObject();
//	doAdopt(sfas97rd_persObj, Node::COUNTED); // delete called by node dtor.
	if (sm_sfas97rd.IsValidSubModelOfBaseModelClass()){
		sm_sfas97rd.resize(0);
		delete sm_sfas97rd.getPersistentObject();
		sm_sfas97rd.mPersistentObj = 0;
	}

}
