void SEG_COMP::resetValues(int decrement) {
   // Reset submodels for next variation/layer
	ptr_tt_avr_components->reset();  // reset temporary table
	ptr_tt_avr_components_bef_sale->reset();  // reset temporary table
	ptr_tt_imr_aft_tax_realzd_cap_gains_bonds->reset();  // reset temporary table
	ptr_tt_imr_aft_tax_realzd_cap_gains_bonds_bef_sale->reset();  // reset temporary table
	ptr_tt_imr_aft_tax_realzd_cap_gains_mortgages->reset();  // reset temporary table
	ptr_tt_imr_aft_tax_realzd_cap_gains_mortgages_bef_sale->reset();  // reset temporary table
	ptr_tt_imr_aft_tax_realzd_cap_gains_other->reset();  // reset temporary table
	ptr_tt_imr_aft_tax_realzd_cap_gains_other_bef_sale->reset();  // reset temporary table
	ptr_tt_imr_aft_tax_realzd_cap_gains_rml->reset();  // reset temporary table
	ptr_tt_imr_aft_tax_realzd_cap_gains_rml_bef_sale->reset();  // reset temporary table
	ptr_tt_imr_amortzn_amt_tbl->reset();  // reset temporary table
	ptr_tt_imr_amortzn_amt_tbl_bef_sale->reset();  // reset temporary table
	ptr_tt_imr_fy_amortzn_for_mth->reset();  // reset temporary table
	ptr_tt_imr_fy_amortzn_for_mth_bef_sale->reset();  // reset temporary table
	ptr_tt_tax_capzd_prem_amortzn_sched->reset();  // reset temporary table
	ModelClass::resetValues(decrement);
}
